#include <iostream>
#include <cmath>
int main()
{
    std::cout << pow(2, 4) << "\n";
    std::cout << fmod(11.5, 2) << "\n";
    std::cout << ceil(9.1) << "\n";
    std::cout << floor(9.1) << "\n";
    std::cout << round(9.5) << "\n";
    std::cout << round(9.49) << "\n";
    std::cout << trunc(9.9) << "\n";
    std::cout << trunc(9.5) << "\n";
    std::cout << trunc(9.1) << "\n";
    return 0;
}